{
    std::lock_guard<std::mutex> lock(g_aclshmem_ctx_mutex);
    if (!is_valid_rdma_qp_num(qp_num)) {
        SHM_LOG_ERROR("invalid qp num: " << qp_num);
        return ACLSHMEM_INVALID_VALUE;
    }
